TOOLCHAIN="/home/wsb/openvela/prebuilts/sg2000_toolchain/host-tools/gcc/riscv64-elf-x86_64/bin"
# Try different nm variants
for nm in "${TOOLCHAIN}/riscv64-unknown-elf-nm" "riscv64-unknown-elf-nm" "llvm-nm"; do
    if command -v "$nm" &>/dev/null; then
        echo "=== Using $nm ==="
        "$nm" -n nuttx/nuttx 2>/dev/null | awk -v epc="80220c9a" -v ret="8020157e" '
        BEGIN { epc_dec = strtonum("0x" epc); ret_dec = strtonum("0x" ret) }
        {
            addr = strtonum("0x" $1)
            if (addr <= epc_dec && $1 != "") { last_before_epc = $0; last_addr_epc = $1 }
            if (addr <= ret_dec && $1 != "") { last_before_ret = $0; last_addr_ret = $1 }
        }
        END {
            print "--- Near EPC " epc " ---"
            print last_before_epc
            print "--- Near Return addr " ret " ---"
            print last_before_ret
        }'
        break
    fi
done

