85	/****************************************************************************
86	 * Name: elf_loadbinary
87	 *
88	 * Description:
89	 *   Verify that the file is an ELF binary and, if so, load the ELF
90	 *   binary into memory
91	 *
92	 ****************************************************************************/
93	
94	static int elf_loadbinary(FAR struct binary_s *binp,
95	                          FAR const char *filename,
96	                          FAR const struct symtab_s *exports,
97	                          int nexports)
98	{
99	  struct mod_loadinfo_s loadinfo;
100	  Elf_Sym sym;
101	  int ret;
102	
103	  binfo("Loading file: %s\n", filename);
104	
105	  /* Initialize the ELF library to load the program binary. */
106	
107	  ret = libelf_initialize(filename, &loadinfo);
108	  libelf_dumploadinfo(&loadinfo);
109	  if (ret != 0)
110	    {
111	      goto errout_with_init;
112	    }
113	
114	  /* Load the program binary */
115	
116	  ret = libelf_load_with_addrenv(&loadinfo, false);
117	  libelf_dumploadinfo(&loadinfo);
118	  if (ret != 0)
119	    {
120	      berr("Failed to load ELF program binary: %d\n", ret);
121	      goto errout_with_init;
122	    }
123	
124	  /* Bind the program to the exported symbol table */
125	
126	  if (loadinfo.ehdr.e_type == ET_REL
127	#ifdef CONFIG_LIBC_ELF_GOT
128	      || loadinfo.gotindex >= 0
129	#endif
130	     )
131	    {
132	      ret = libelf_bind(&binp->mod, &loadinfo, exports, nexports);
133	      if (ret != 0)
134	        {
135	          berr("Failed to bind symbols program binary: %d\n", ret);
136	          goto errout_with_load;
137	        }
138	
139	      binp->entrypt = (main_t)(loadinfo.textalloc + loadinfo.ehdr.e_entry);
140	    }
141	  else if (loadinfo.ehdr.e_type == ET_EXEC)
142	    {
143	      if (nexports > 0)
144	        {
145	          berr("Cannot bind exported symbols to a "
146	               "fully linked executable\n");
147	          ret = -ENOEXEC;
148	          goto errout_with_load;
149	        }
150	
151	      /* The entrypoint for a fully linked executable can be found directly */
152	
153	      binp->entrypt = (main_t)(loadinfo.ehdr.e_entry);
154	    }
155	
156	  else
157	    {
158	      berr("Unexpected elf type %d\n", loadinfo.ehdr.e_type);
159	      ret = -ENOEXEC;
160	      goto errout_with_load;
161	    }
162	
163	  /* Return the load information */
164	
165	  ret = libelf_findsymbol(&loadinfo, "nx_stacksize", &sym);
166	  if (ret == 0)
167	    {
168	      binp->stacksize = sym.st_value;
169	    }
170	  else
171	    {
172	      binp->stacksize = CONFIG_ELF_STACKSIZE;
173	    }
174	
175	  ret = libelf_findsymbol(&loadinfo, "nx_priority", &sym);
176	  if (ret == 0)
177	    {
178	      binp->priority = sym.st_value;
179	    }

155	int load_module(FAR struct binary_s *bin, FAR const char *filename,
