94	/****************************************************************************
95	 * Name: libelf_readrels
96	 *
97	 * Description:
98	 *   Read the (ELF_Rel structure * buffer count) into memory.
99	 *
100	 ****************************************************************************/
101	
102	static inline int libelf_readrels(FAR struct mod_loadinfo_s *loadinfo,
103	                                  FAR const Elf_Shdr *relsec,
104	                                  int index, FAR Elf_Rel *rels,
105	                                  int count)
106	{
107	  off_t offset;
108	  int size;
109	
110	  /* Verify that the symbol table index lies within symbol table */
111	
112	  if (index < 0 || index > (relsec->sh_size / sizeof(Elf_Rel)))
113	    {
114	      berr("ERROR: Bad relocation symbol index: %d\n", index);
115	      return -EINVAL;
116	    }
117	
118	  /* Get the file offset to the symbol table entry */
119	
120	  offset = sizeof(Elf_Rel) * index;
121	  size   = sizeof(Elf_Rel) * count;
122	  if (offset + size > relsec->sh_size)
123	    {
124	      size = relsec->sh_size - offset;
125	    }
126	
127	  /* And, finally, read the symbol table entry into memory */
128	
129	  return libelf_read(loadinfo, (FAR uint8_t *)rels, size,
130	                     relsec->sh_offset + offset);
131	}
