172	/****************************************************************************
173	 * Name: libelf_relocate and libelf_relocateadd
174	 *
175	 * Description:
176	 *   Perform all relocations associated with a section.
177	 *
178	 * Returned Value:
179	 *   0 (OK) is returned on success and a negated errno is returned on
180	 *   failure.
181	 *
182	 ****************************************************************************/
183	
184	static int libelf_relocate(FAR struct module_s *modp,
185	                           FAR struct mod_loadinfo_s *loadinfo, int relidx,
186	                           FAR const struct symtab_s *exports, int nexports)
187	{
188	  FAR Elf_Shdr     *relsec = &loadinfo->shdr[relidx];
189	  FAR Elf_Shdr     *dstsec = &loadinfo->shdr[relsec->sh_info];
190	  FAR Elf_Rel      *rels;
191	  FAR Elf_Rel      *rel;
192	  FAR Elf_SymCache *cache;
193	  FAR Elf_Sym      *sym;
194	  FAR dq_entry_t   *e;
195	  dq_queue_t        q;
196	  uintptr_t         addr;
197	  int               symidx;
198	  int               ret = OK;
199	  int               i;
200	  int               j;
201	
202	  /* Define potential architecture specific elf data container */
203	
204	  ARCH_ELFDATA_DEF;
205	
206	  rels = lib_malloc(CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT *
207	                    sizeof(Elf_Rel));
208	  if (!rels)
209	    {
210	      berr("Failed to allocate memory for elf relocation rels\n");
211	      return -ENOMEM;
212	    }
213	
214	  dq_init(&q);
215	
216	  /* Examine each relocation in the section.  'relsec' is the section
217	   * containing the relations.  'dstsec' is the section containing the data
218	   * to be relocated.
219	   */
220	
221	  for (i = j = 0; i < relsec->sh_size / sizeof(Elf_Rel); i++)
222	    {
223	      /* Read the relocation entry into memory */
224	
225	      rel = &rels[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
226	
227	      if (!(i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT))
228	        {
229	          ret = libelf_readrels(loadinfo, relsec, i, rels,
230	                                CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT);
231	          if (ret < 0)
232	            {
233	              berr("ERROR: Section %d reloc %d: "
234	                   "Failed to read relocation entry: %d\n",
235	                   relidx, i, ret);
236	              break;
237	            }
238	        }
239	
240	      /* Get the symbol table index for the relocation.  This is contained
241	       * in a bit-field within the r_info element.
242	       */
243	
244	      symidx = ELF_R_SYM(rel->r_info);
245	
246	      /* First try the cache */
247	
248	      sym = NULL;
249	      for (e = dq_peek(&q); e; e = dq_next(e))
250	        {
251	          cache = (FAR Elf_SymCache *)e;
252	          if (cache->idx == symidx)
253	            {
254	              dq_rem(&cache->entry, &q);
255	              dq_addfirst(&cache->entry, &q);
256	              sym = &cache->sym;
257	              break;
258	            }
259	        }
260	
261	      /* If the symbol was not found in the cache, we will need to read the
262	       * symbol from the file.
263	       */
264	
265	      if (sym == NULL)
266	        {
267	          if (j < CONFIG_LIBC_ELF_SYMBOL_CACHECOUNT)
268	            {
269	              cache = lib_malloc(sizeof(Elf_SymCache));
270	              if (!cache)
271	                {
272	                  berr("Failed to allocate memory for elf symbols\n");
273	                  ret = -ENOMEM;
274	                  break;
275	                }
276	
277	              j++;
278	            }
279	          else
280	            {
281	              cache = (FAR Elf_SymCache *)dq_remlast(&q);
282	            }
283	
284	          sym = &cache->sym;
285	
286	          /* Read the symbol table entry into memory */
287	
288	          ret = libelf_readsym(loadinfo, symidx, sym,
289	                               &loadinfo->shdr[loadinfo->symtabidx]);
290	          if (ret < 0)
291	            {
292	              berr("ERROR: Section %d reloc %d: "
293	                   "Failed to read symbol[%d]: %d\n",
294	                   relidx, i, symidx, ret);
295	              lib_free(cache);
296	              break;
297	            }
298	
299	          /* Get the value of the symbol (in sym.st_value) */
300	
301	          ret = libelf_symvalue(modp, loadinfo, sym,
302	                  loadinfo->shdr[loadinfo->strtabidx].sh_offset,
303	                  exports, nexports);
304	          if (ret < 0)
305	            {
306	              /* The special error -ESRCH is returned only in one condition:
307	               * The symbol has no name.
308	               *
309	               * There are a few relocations for a few architectures that do
310	               * no depend upon a named symbol.  We don't know if that is the
311	               * case here, but we will use a NULL symbol pointer to indicate
312	               * that case to up_relocate().  That function can then do what
313	               * is best.
314	               */
315	
316	              if (ret == -ESRCH)
317	                {
318	                  berr("ERROR: Section %d reloc %d: "
319	                       "Undefined symbol[%d] has no name: %d\n",
320	                       relidx, i, symidx, ret);
321	                }
322	              else
323	                {
324	                  berr("ERROR: Section %d reloc %d: "
325	                       "Failed to get value of symbol[%d]: %d\n",
326	                       relidx, i, symidx, ret);
327	                  lib_free(cache);
328	                  break;
329	                }
330	            }
331	
332	          cache->idx = symidx;
333	          dq_addfirst(&cache->entry, &q);
334	        }
335	
336	      if (sym->st_shndx == SHN_UNDEF && sym->st_name == 0)
337	        {
338	          sym = NULL;
339	        }
340	
341	      /* Calculate the relocation address. */
342	
343	#ifdef CONFIG_LIBC_ELF_GOT
344	      if (loadinfo->gotindex >= 0)
345	        {
346	          if (sym->st_shndx == SHN_UNDEF)
347	            {
348	              /* Symbol type is undefined, we need to set the address
349	               * to the value of the symbol.
350	               */
351	
352	              FAR Elf_Shdr *gotsec = &loadinfo->shdr[loadinfo->gotindex];
353	              FAR uintptr_t *gotaddr = (FAR uintptr_t *)(gotsec->sh_addr +
354	                *((FAR uintptr_t *)(dstsec->sh_addr + rel->r_offset)));
355	
356	              *gotaddr = sym->st_value;
357	              continue;
358	            }
359	
360	          if ((dstsec->sh_flags & SHF_WRITE) == 0)
361	            {
362	              /* Skip relocations for read-only sections */
363	
364	              continue;
365	            }
366	
367	          /* Use the GOT to store the address */
368	
369	          if (rel->r_offset - dstsec->sh_offset >
370	              dstsec->sh_size)
371	            {
372	              berr("ERROR: Section %d reloc %d: "
373	                   "Relocation address out of range, "
374	                   "offset %" PRIuPTR " size %ju\n",
375	                   relidx, i, (uintptr_t)rel->r_offset,
376	                   (uintmax_t)dstsec->sh_size);
377	              ret = -EINVAL;
378	              break;
379	            }
380	
381	          addr = dstsec->sh_addr + rel->r_offset - dstsec->sh_offset;
382	          if (ELF_ST_TYPE(sym->st_info) == STT_SECTION)
383	            {
384	              /* Symbol type is section, we need clear the address
385	               * and keep the original value.
386	               */
387	
388	              *(FAR uintptr_t *)addr -=
389	                 loadinfo->shdr[sym->st_shndx].sh_offset;
390	            }
391	          else
392	            {
393	              /* Normal symbol, just keep it zero */
394	
395	              *(FAR uintptr_t *)addr = 0;
396	            }
397	        }
398	      else
399	#endif
400	        {
401	          if (rel->r_offset > dstsec->sh_size)
402	            {
403	              berr("ERROR: Section %d reloc %d: "
404	                   "Relocation address out of range, "
405	                   "offset %" PRIuPTR " size %ju\n",
406	                   relidx, i, (uintptr_t)rel->r_offset,
407	                   (uintmax_t)dstsec->sh_size);
408	              ret = -EINVAL;
409	              break;
410	            }
411	
412	          addr = dstsec->sh_addr + rel->r_offset;
413	        }
414	
415	      /* Now perform the architecture-specific relocation */
416	
417	      ret = up_relocate(rel, sym, addr, ARCH_ELFDATA_PARM);
418	      if (ret < 0)
419	        {
420	          berr("ERROR: Section %d reloc %d: Relocation failed: %d\n",
421	               relidx, i, ret);
422	          break;
423	        }
424	    }
425	
426	  lib_free(rels);
427	  while ((e = dq_peek(&q)) != NULL)
428	    {
429	      dq_rem(e, &q);
430	      lib_free(e);
431	    }
432	
433	  return ret;
434	}
435	
436	static int libelf_relocateadd(FAR struct module_s *modp,
437	                              FAR struct mod_loadinfo_s *loadinfo,
438	                              int relidx,
439	                              FAR const struct symtab_s *exports,
440	                              int nexports)
441	{
442	  FAR Elf_Shdr     *relsec = &loadinfo->shdr[relidx];
443	  FAR Elf_Shdr     *dstsec = &loadinfo->shdr[relsec->sh_info];
444	  FAR Elf_Rela     *relas;
445	  FAR Elf_Rela     *rela;
446	  FAR Elf_SymCache *cache;
447	  FAR Elf_Sym      *sym;
448	  FAR dq_entry_t   *e;
449	  dq_queue_t        q;
450	  uintptr_t         addr;
451	  int               symidx;
452	  int               ret = OK;
453	  int               i;
454	  int               j;
455	
456	  /* Define potential architecture specific elf data container */
457	
458	  ARCH_ELFDATA_DEF;
459	
460	  relas = lib_malloc(CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT *
461	                     sizeof(Elf_Rela));
462	  if (!relas)
463	    {
464	      berr("Failed to allocate memory for elf relocation relas\n");
465	      return -ENOMEM;
466	    }
467	
468	  dq_init(&q);
469	
470	  /* Examine each relocation in the section.  'relsec' is the section
471	   * containing the relations.  'dstsec' is the section containing the data
472	   * to be relocated.
473	   */
474	
475	  for (i = j = 0; i < relsec->sh_size / sizeof(Elf_Rela); i++)
476	    {
477	      /* Read the relocation entry into memory */
478	
479	      rela = &relas[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
480	
481	      if (!(i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT))
482	        {
483	          ret = libelf_readrelas(loadinfo, relsec, i, relas,
484	                                 CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT);
485	          if (ret < 0)
486	            {
487	              berr("ERROR: Section %d reloc %d: "
488	                   "Failed to read relocation entry: %d\n",
489	                   relidx, i, ret);
490	              break;
491	            }
492	        }
493	
494	      /* Get the symbol table index for the relocation.  This is contained
495	       * in a bit-field within the r_info element.
496	       */
497	
498	      symidx = ELF_R_SYM(rela->r_info);
499	
500	      /* First try the cache */
501	
502	      sym = NULL;
503	      for (e = dq_peek(&q); e; e = dq_next(e))
504	        {
505	          cache = (FAR Elf_SymCache *)e;
506	          if (cache->idx == symidx)
507	            {
508	              dq_rem(&cache->entry, &q);
509	              dq_addfirst(&cache->entry, &q);
510	              sym = &cache->sym;
511	              break;
512	            }
513	        }
514	
515	      /* If the symbol was not found in the cache, we will need to read the
516	       * symbol from the file.
517	       */
518	
519	      if (sym == NULL)
520	        {
521	          if (j < CONFIG_LIBC_ELF_SYMBOL_CACHECOUNT)
522	            {
523	              cache = lib_malloc(sizeof(Elf_SymCache));
524	              if (!cache)
525	                {
526	                  berr("Failed to allocate memory for elf symbols\n");
527	                  ret = -ENOMEM;
528	                  break;
529	                }
530	
531	              j++;
532	            }
533	          else
534	            {
535	              cache = (FAR Elf_SymCache *)dq_remlast(&q);
536	            }
537	
538	          sym = &cache->sym;
539	
540	          /* Read the symbol table entry into memory */
541	
542	          ret = libelf_readsym(loadinfo, symidx, sym,
543	                               &loadinfo->shdr[loadinfo->symtabidx]);
544	          if (ret < 0)
545	            {
546	              berr("ERROR: Section %d reloc %d: "
547	                   "Failed to read symbol[%d]: %d\n",
548	                   relidx, i, symidx, ret);
549	              lib_free(cache);
550	              break;
551	            }
552	
553	          /* Get the value of the symbol (in sym.st_value) */
554	
555	          ret = libelf_symvalue(modp, loadinfo, sym,
556	                           loadinfo->shdr[loadinfo->strtabidx].sh_offset,
557	                           exports, nexports);
558	          if (ret < 0)
559	            {
560	              /* The special error -ESRCH is returned only in one condition:
561	               * The symbol has no name.
562	               *
563	               * There are a few relocations for a few architectures that do
564	               * no depend upon a named symbol.  We don't know if that is the
565	               * case here, but we will use a NULL symbol pointer to indicate
566	               * that case to up_relocate().  That function can then do what
567	               * is best.
568	               */
569	
570	              if (ret == -ESRCH)
571	                {
572	                  berr("ERROR: Section %d reloc %d: "
573	                       "Undefined symbol[%d] has no name: %d\n",
574	                       relidx, i, symidx, ret);
575	                }
576	              else
577	                {
578	                  berr("ERROR: Section %d reloc %d: "
579	                       "Failed to get value of symbol[%d]: %d\n",
580	                       relidx, i, symidx, ret);
581	                  lib_free(cache);
582	                  break;
583	                }
584	            }
585	
586	          cache->idx = symidx;
587	          dq_addfirst(&cache->entry, &q);
588	        }
589	
590	      if (sym->st_shndx == SHN_UNDEF && sym->st_name == 0)
591	        {
592	          sym = NULL;
593	        }
594	
595	      /* Calculate the relocation address. */
596	
597	      if (rela->r_offset > dstsec->sh_size)
598	        {
599	          berr("ERROR: Section %d reloc %d: "
600	               "Relocation address out of range, "
601	               "offset %" PRIuPTR " size %ju\n",
602	               relidx, i, (uintptr_t)rela->r_offset,
603	               (uintmax_t)dstsec->sh_size);
604	          ret = -EINVAL;
605	          break;
606	        }
607	
608	      addr = dstsec->sh_addr + rela->r_offset;
609	
610	      /* Now perform the architecture-specific relocation */
611	
612	      ret = up_relocateadd(rela, sym, addr, ARCH_ELFDATA_PARM);
613	      if (ret < 0)
614	        {
615	          berr("ERROR: Section %d reloc %d: Relocation failed: %d\n",
616	               relidx, i, ret);
617	          break;
618	        }
619	    }
620	
621	  lib_free(relas);
622	  while ((e = dq_peek(&q)) != NULL)
623	    {
624	      dq_rem(e, &q);
625	      lib_free(e);
626	    }
627	
628	  return ret;
629	}
