631	/****************************************************************************
632	 * Name: libelf_relocatedyn
633	 *
634	 * Description:
635	 *   Perform all relocations associated with a dynamic section.
636	 *
637	 * Returned Value:
638	 *   0 (OK) is returned on success and a negated errno is returned on
639	 *   failure.
640	 *
641	 ****************************************************************************/
642	
643	static int libelf_relocatedyn(FAR struct module_s *modp,
644	                              FAR struct mod_loadinfo_s *loadinfo,
645	                              int relidx)
646	{
647	  FAR Elf_Shdr *shdr = &loadinfo->shdr[relidx];
648	  FAR Elf_Shdr *symhdr;
649	  FAR Elf_Dyn  *dyn = NULL;
650	  FAR Elf_Rel  *rels = NULL;
651	  FAR Elf_Rel  *rel;
652	  FAR Elf_Rela *relas = NULL;
653	  FAR Elf_Rela *rela;
654	  FAR Elf_Sym  *sym = NULL;
655	  uintptr_t     addr;
656	  int           ret;
657	  int           i;
658	  int           idx_rel;
659	  int           idx_sym;
660	
661	  /* Define potential architecture specific elf data container */
662	
663	  ARCH_ELFDATA_DEF;
664	
665	  dyn = lib_malloc(shdr->sh_size);
666	  if (dyn == NULL)
667	    {
668	      berr("Failed to allocate memory for elf dynamic section\n");
669	      return -ENOMEM;
670	    }
671	
672	  ret = libelf_read(loadinfo, (FAR uint8_t *)dyn, shdr->sh_size,
673	                    shdr->sh_offset);
674	  if (ret < 0)
675	    {
676	      berr("Failed to read dynamic section header");
677	      lib_free(dyn);
678	      return ret;
679	    }
680	
681	  /* Assume DT_RELA to get maximum size required */
682	
683	  rels = lib_zalloc(CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT *
684	                    sizeof(Elf_Rela));
685	  if (!rels)
686	    {
687	      berr("Failed to allocate memory for elf relocation rels\n");
688	      lib_free(dyn);
689	      return -ENOMEM;
690	    }
691	
692	  memset((FAR void *)&reldata, 0, sizeof(reldata));
693	  relas = (FAR Elf_Rela *)rels;
694	
695	  for (i = 0; dyn[i].d_tag != DT_NULL; i++)
696	    {
697	      switch (dyn[i].d_tag)
698	        {
699	          case DT_REL:
700	            reldata.reloff[I_REL] = dyn[i].d_un.d_val;
701	            break;
702	          case DT_RELSZ:
703	            reldata.relsz[I_REL] = dyn[i].d_un.d_val;
704	            break;
705	          case DT_RELENT:
706	            reldata.relentsz[I_REL] = dyn[i].d_un.d_val;
707	            break;
708	          case DT_SYMTAB:
709	            reldata.symoff = dyn[i].d_un.d_val;
710	            break;
711	          case DT_STRTAB:
712	            reldata.stroff = dyn[i].d_un.d_val;
713	            break;
714	          case DT_JMPREL:
715	            reldata.reloff[I_PLT] = dyn[i].d_un.d_val;
716	            break;
717	          case DT_PLTRELSZ:
718	            reldata.relsz[I_PLT] = dyn[i].d_un.d_val;
719	            break;
720	          case DT_PLTREL:
721	            if (dyn[i].d_un.d_val == DT_REL)
722	              {
723	                reldata.relentsz[I_PLT] = sizeof(Elf_Rel);
724	                reldata.relrela[I_PLT] = 0;
725	              }
726	            else
727	              {
728	                reldata.relentsz[I_PLT] = sizeof(Elf_Rela);
729	                reldata.relrela[I_PLT] = 1;
730	              }
731	            break;
732	        }
733	    }
734	
735	  symhdr = &loadinfo->shdr[loadinfo->dsymtabidx];
736	  sym = lib_malloc(symhdr->sh_size);
737	  if (!sym)
738	    {
739	      berr("Error obtaining storage for dynamic symbol table");
740	      lib_free(rels);
741	      lib_free(dyn);
742	      return -ENOMEM;
743	    }
744	
745	  ret = libelf_read(loadinfo, (FAR uint8_t *)sym, symhdr->sh_size,
746	                    symhdr->sh_offset);
747	  if (ret < 0)
748	    {
749	      berr("Error reading dynamic symbol table - %d", ret);
750	      lib_free(sym);
751	      lib_free(rels);
752	      lib_free(dyn);
753	      return ret;
754	    }
755	
756	  reldata.lsymtab = reldata.stroff - reldata.symoff;
757	
758	  for (idx_rel = 0; idx_rel < N_RELS; idx_rel++)
759	    {
760	      int lrelent;
761	
762	      if ((reldata.relsz[idx_rel] == 0) || (reldata.reloff[idx_rel] == 0))
763	        {
764	          continue;
765	        }
766	
767	      /* Examine each relocation in the .rel.* section. */
768	
769	      ret = OK;
770	      lrelent = reldata.relsz[idx_rel] / reldata.relentsz[idx_rel];
771	
772	      for (i = 0; i < lrelent; i++)
773	        {
774	          /* Process each relocation entry
775	           * - we cheat by using the fact the 1st two fields of Elf_Rel
776	           *   and Elf_Rela are identical so can do things based on the
777	           *   former until it's important
778	           */
779	
780	          if (reldata.relrela[idx_rel] == 0)
781	            {
782	              rel = &rels[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
783	              rela = (Elf_Rela *)rel;  /* Just to keep the compiler happy */
784	            }
785	          else
786	            {
787	              rela = &relas[i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT];
788	              rel = (Elf_Rel *)rela;
789	            }
790	
791	          if (!(i % CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT))
792	            {
793	              size_t relsize = (sizeof(Elf_Rela) *
794	                               CONFIG_LIBC_ELF_RELOCATION_BUFFERCOUNT);
795	
796	              if (reldata.relsz[idx_rel] < relsize)
797	                {
798	                  relsize = reldata.relsz[idx_rel];
799	                }
800	
801	              ret = libelf_read(loadinfo, (FAR uint8_t *)rels,
802	                                relsize,
803	                                reldata.reloff[idx_rel] +
804	                                i * sizeof(Elf_Rel));
805	
806	              if (ret < 0)
807	                {
808	                  berr("ERROR: Section %d reloc %d:"
809	                       "Failed to read relocation entry: %d\n",
810	                       relidx, i, ret);
811	                  break;
812	                }
813	            }
814	
815	          /* Now perform the architecture-specific relocation */
816	
817	          if ((idx_sym = ELF_R_SYM(rel->r_info)) != 0)
818	            {
819	              /* We have an external reference */
820	
821	              if (sym[idx_sym].st_shndx == SHN_UNDEF)
822	                {
823	                    FAR void *ep;
824	
825	                    ep = libelf_findglobal(modp, loadinfo, symhdr,
826	                                           &sym[idx_sym]);
827	                    if ((ep == NULL) && (ELF_ST_BIND(sym[idx_sym].st_info)
828	                        != STB_WEAK))
829	                      {
830	                        berr("ERROR: Unable to resolve addr of ext ref %s\n",
831	                             loadinfo->iobuffer);
832	                        ret = -EINVAL;
833	                        lib_free(sym);
834	                        lib_free(rels);
835	                        lib_free(dyn);
836	                        return ret;
837	                      }
838	
839	                    addr = rel->r_offset + loadinfo->textalloc;
840	
841	                    if (reldata.relrela[idx_rel] == 1)
842	                      {
843	                        addr += rela->r_addend;
844	                      }
845	
846	                    *(FAR uintptr_t *)addr = (uintptr_t)ep;
847	                }
848	            }
849	          else
850	            {
851	              Elf_Sym dynsym =
852	                {
853	                  0
854	                };
855	
856	              addr = rel->r_offset - loadinfo->datasec + loadinfo->datastart;
857	
858	              if (reldata.relrela[idx_rel] == 1)
859	                {
860	                  addr += rela->r_addend;
861	                }
862	
863	              if ((*(FAR uint32_t *)addr) < loadinfo->datasec)
864	                {
865	                  dynsym.st_value = *(FAR uint32_t *)addr +
866	                                    loadinfo->textalloc;
867	                }
868	              else
869	                {
870	                  dynsym.st_value = *(FAR uint32_t *)addr -
871	                                    loadinfo->datasec + loadinfo->datastart;
872	                }
873	
874	              ret = up_relocate(rel, &dynsym, addr, ARCH_ELFDATA_PARM);
875	            }
876	
877	          if (ret < 0)
878	            {
879	              berr("ERROR: Section %d reloc %d: Relocation failed: %d\n",
880	                   relidx, i, ret);
881	              lib_free(sym);
882	              lib_free(rels);
883	              lib_free(dyn);
884	              return ret;
885	            }
886	        }
887	    }
888	
889	  lib_free(sym);
890	  lib_free(rels);
891	  lib_free(dyn);
892	
893	  return ret;
894	}
