900	/****************************************************************************
901	 * Name: libelf_bind
902	 *
903	 * Description:
904	 *   Bind the imported symbol names in the loaded module described by
905	 *   'loadinfo' using the exported symbol values provided by
906	 *   libelf_setsymtab().
907	 *
908	 * Input Parameters:
909	 *   modp     - Module state information
910	 *   loadinfo - Load state information
911	 *   exports  - The table of exported symbols
912	 *   nexports - The number of symbols in the exports table
913	 *
914	 * Returned Value:
915	 *   0 (OK) is returned on success and a negated errno is returned on
916	 *   failure.
917	 *
918	 ****************************************************************************/
919	
920	int libelf_bind(FAR struct module_s *modp,
921	                FAR struct mod_loadinfo_s *loadinfo,
922	                FAR const struct symtab_s *exports, int nexports)
923	{
924	  int ret;
925	  int i;
